    New-ConsoleText $_.About
    New-ConsoleKeyValue -Markup -Data ([ordered] @{ Category = $_.Category; Healthy = "[pass]$($_.Expected)[/]"; Typical = "about $($_.Seconds) s per server"; Parameter = "[accent]-Check $_[/]" })
}
