using System.Globalization;
using ConsoleMonster.Live;

// Forty servers patched eight at a time. Three fail and one hangs past the four-second limit;
// the view lists the failures and the results keep them for the rest of the program.
IEnumerable<string> servers = Enumerable.Range(1, 40).Select(n => "web" + n.ToString("00", CultureInfo.InvariantCulture));
IReadOnlyList<RunResult<string, string>> results = await ConsoleRun.ForEachAsync(servers, async (server, cancel) => {
    int number = int.Parse(server.Substring(3), CultureInfo.InvariantCulture);
    await Task.Delay(500 + number * 137 % 900, cancel);
    if (number % 13 == 0) {
        throw new InvalidOperationException(server + " did not come back after the reboot");
    }
    if (number == 22) {
        await Task.Delay(TimeSpan.FromSeconds(10), cancel);
    }
    return server + " patched";
}, new RunOptions { ThrottleLimit = 8, Timeout = TimeSpan.FromSeconds(4), Title = "Patching the web farm" });

watch.powershell:
# The mail queues every 1.5 seconds; -Differences marks the cells that changed since the last run.
$script:tick = 0
Watch-Console -Title 'Mail queues' -Interval 1.5 -Count 6 -Differences {
    $script:tick++
    $servers = 'MX01', 'MX02', 'MX03', 'MX04'
    for ($i = 0; $i -lt $servers.Count; $i++) {
        $load = ($script:tick * 7 + $i * 3) % 11
        [pscustomobject] @{
            Server    = "$($servers[$i]).evotec.xyz"
            Queued    = $load * 4
            Deferred  = if ($i -eq 2) { 12 + $script:tick * 5 } else { $load % 3 }
            Delivered = 1200 + $script:tick * 85 + $load * 9
            Status    = if ($i -eq 2 -and $script:tick -gt 2) { 'Warn' } else { 'Pass' }
        }
    }
}

