} catch (TimeoutException ex) {
    orders.LogError(ex, "Refund for order {Id} failed", 1038);
}
orders.LogCritical("Queue {Queue} is not draining", "orders-eu");
orders.LogInformation("Done; {Processed} orders processed", 57);

